export default "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Events</title>\n<style>\n:root{--bg:#00414B;--card:#012C33;--stroke:#1E7480;--acc:#4FE3D0;--txt:#E8F6F5;--dim:#8FBCC0;--red:#E5584D;--grn:#5CE0A0;--amb:#FFB020}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font:15px system-ui,sans-serif;padding:14px}\n.w{max-width:640px;margin:0 auto}h1{font-size:20px;color:var(--acc);margin:4px 0 10px}\n.c{background:var(--card);border:1px solid var(--stroke);border-radius:14px;padding:13px;margin-bottom:12px}\ninput,textarea{width:100%;background:#01242A;color:var(--txt);border:1px solid var(--stroke);border-radius:10px;padding:10px;font:inherit;margin:5px 0}\ntextarea{min-height:70px;font-family:ui-monospace,monospace;font-size:13px}\nbutton{background:var(--acc);color:#00282e;border:0;border-radius:10px;padding:8px 12px;font-weight:600;font-size:14px}\nbutton.s{background:transparent;color:var(--acc);border:1px solid var(--stroke)}button.d{background:transparent;color:var(--red);border:1px solid var(--red)}button.sm{padding:5px 9px;font-size:13px}\nbutton[disabled]{opacity:.4}\n.bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px;color:var(--dim);font-size:13px}.bar .g{flex:1}\n.t{display:flex;justify-content:space-between;gap:8px;align-items:baseline}.t b{font-size:17px}\n.pill{font-size:12px;padding:2px 8px;border-radius:99px;border:1px solid var(--stroke);color:var(--dim)}.pill.live{border-color:var(--grn);color:var(--grn)}.pill.ended{opacity:.6}\n.m{color:var(--dim);font-size:13px;margin:3px 0}.cd{color:var(--amb);font-weight:700}\n.r{display:flex;align-items:center;gap:8px;padding:7px 0;border-top:1px solid #0d4a54}.r .n{flex:1;min-width:0}.r small{color:var(--dim)}\n.h{font-size:11px;color:var(--dim);letter-spacing:.07em;margin:10px 0 2px}\n.me{color:var(--grn)}.msg{color:var(--amb);min-height:18px;font-size:13px}\n.row2{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n</style></head><body><div class=\"w\">\n<h1 id=\"ttl\">Events</h1>\n<div class=\"bar\"><span id=\"who\" class=\"g\"></span><button class=\"s sm\" id=\"acctB\"></button><button class=\"s sm\" id=\"mgrB\">Manager</button></div>\n<div class=\"msg\" id=\"msg\"></div>\n<div class=\"c\" id=\"login\" style=\"display:none\"><b id=\"lgT\"></b>\n<input id=\"un\" autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\"><input id=\"pw\" type=\"password\" autocomplete=\"current-password\">\n<div style=\"display:flex;gap:8px\"><button id=\"lgIn\"></button><button class=\"s\" id=\"lgReg\"></button><button class=\"s\" id=\"lgX\"></button></div></div>\n<div class=\"c\" id=\"mgr\" style=\"display:none\"><b>Create event</b>\n<input id=\"mt\" placeholder=\"Title\" maxlength=\"80\"><input id=\"md\" placeholder=\"Description (optional)\" maxlength=\"600\">\n<div class=\"row2\"><input id=\"ms\" type=\"datetime-local\"><input id=\"mh\" type=\"number\" step=\"0.5\" min=\"0.5\" max=\"24\" value=\"3\" placeholder=\"Hours\"></div>\n<div class=\"m\">Start time is UTC. Duration in hours.</div>\n<div class=\"row2\"><input id=\"ma\" placeholder=\"Airport (ICAO, optional)\" maxlength=\"8\"><input id=\"mr\" placeholder=\"Route (optional)\" maxlength=\"300\"></div>\n<div class=\"h\">PILOT SLOTS (one per line: CALLSIGN DEP ARR)</div><textarea id=\"mp\" placeholder=\"AFS101 SBBR SBGR&#10;AFS102 SBBR SBGR\"></textarea>\n<div class=\"h\">CONTROLLER SLOTS (one per line: AIRPORT ROLE, role = GND TWR APP CTR)</div><textarea id=\"mc\" placeholder=\"SBBR TWR&#10;SBBR APP\"></textarea>\n<button id=\"mgo\">Create event</button></div>\n<div id=\"list\"></div>\n</div>\n<script>\n(function(){\nvar $=function(i){return document.getElementById(i)},qs=new URLSearchParams(location.search);\nvar lang=(qs.get('lang')||(navigator.language||'en')).slice(0,2)==='pt'?'pt':'en',L=function(e,p){return lang==='pt'?p:e};\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]})}\nfunction ls(k,v){try{if(v===undefined)return localStorage.getItem(k)||'';if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch(e){return''}}\nvar dev=ls('abflug_key');if(!dev){dev='ev'+Math.random().toString(16).slice(2,18);ls('abflug_key',dev)}\nvar tok=qs.get('key')&&qs.get('key').indexOf('afa_')===0?qs.get('key'):ls('afc_token'),acct=ls('afc_acct'),mc=ls('afc_mgr'),data=[],nowOff=0,showMgr=false;\nfunction key(){return tok||qs.get('key')||dev}\nfunction api(m,p,b,extra){var h={'X-API-Key':key(),'Content-Type':'application/json'};if(mc)h['X-Manager']=mc;return fetch(p,{method:m,headers:h,body:b?JSON.stringify(b):undefined}).then(function(r){return r.json().catch(function(){return{}}).then(function(j){return{s:r.status,j:j}})})}\nfunction say(t){$('msg').textContent=t||''}\nvar ERR={account_required:['Sign in to take a slot','Entre na conta para pegar uma vaga'],slot_taken:['That slot was just taken','Essa vaga acabou de ser ocupada'],already_signed:['You already have a slot of that type in this event','Voc\u00ea j\u00e1 tem uma vaga desse tipo neste evento'],event_over:['This event is over','O evento terminou'],not_manager:['Manager code needed','C\u00f3digo de gerente necess\u00e1rio']};\nfunction err(r){var e=ERR[r.j&&r.j.error];say(e?L(e[0],e[1]):(r.j&&r.j.error)||('HTTP '+r.s))}\nfunction utc(t){var d=new Date(t);return d.toISOString().slice(0,16).replace('T',' ')+' UTC'}\nfunction loc(t){return new Date(t).toLocaleString([],{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}\nfunction cd(e){var n=Date.now()+nowOff,d=e.start-n;if(d>0){var s=Math.floor(d/1000),dd=Math.floor(s/86400),hh=Math.floor(s%86400/3600),mm=Math.floor(s%3600/60),ss=s%60;return L('Starts in ','Come\u00e7a em ')+(dd?dd+'d ':'')+(dd||hh?hh+'h ':'')+mm+'m '+(dd?'':ss+'s')}\n  if(n<=e.end)return L('Live now','Ao vivo agora');return L('Ended','Encerrado')}\nfunction stateOf(e){var n=Date.now()+nowOff;return n<e.start?'upcoming':n<=e.end?'live':'ended'}\nfunction fmtT(sec){sec=Math.round(sec||0);var h=Math.floor(sec/3600),m=Math.floor(sec%3600/60);return h?h+'h '+m+'m':m+' min'}\nfunction recLine(s,kind){var r=s.rec;if(!r)return'';return'<br><small class=\"rec\">'+(kind==='p'?fmtT(r.flight_s)+' '+L('flown','voados')+' &middot; '+r.flights+' '+L('flights','voos')+' &middot; '+r.landings+' '+L('landings','pousos'):fmtT(r.atc_s)+' '+L('on position','na posi\u00e7\u00e3o'))+'</small>'}\nfunction recap(e){var t={f:0,fl:0,ld:0,a:0,np:0,nc:0};e.pilots.forEach(function(s){if(s.rec){t.f+=s.rec.flight_s;t.fl+=s.rec.flights;t.ld+=s.rec.landings;t.np++}});e.ctl.forEach(function(s){if(s.rec){t.a+=s.rec.atc_s;t.nc++}});\n  if(!t.np&&!t.nc)return'';return'<div class=\"h\">'+L('RECAP','RESUMO')+'</div><div class=\"m\" style=\"color:var(--txt)\">'+t.np+' '+L('pilots','pilotos')+' &middot; '+fmtT(t.f)+' &middot; '+t.fl+' '+L('flights','voos')+' &middot; '+t.ld+' '+L('landings','pousos')+'<br>'+t.nc+' '+L('controllers','controladores')+' &middot; '+fmtT(t.a)+' ATC</div>'}\nfunction slotRow(ev,s,kind){var lbl=kind==='p'?'<b>'+esc(s.callsign)+'</b> <small>'+esc(s.dep||'----')+' &rarr; '+esc(s.arr||'----')+'</small>':'<b>'+esc(s.apt)+' '+esc(s.pos)+'</b>';\n  var who=s.taken?'<span class=\"'+(s.mine?'me':'')+'\">'+esc(s.name)+(s.mine?' ('+L('you','voc\u00ea')+')':'')+'</span>':'<small>'+L('free','livre')+'</small>';\n  var b='';if(s.mine)b='<button class=\"s sm\" data-act=\"leave\" data-id=\"'+ev.id+'\" data-slot=\"'+s.slot+'\">'+L('Leave','Sair')+'</button>';\n  else if(!s.taken&&stateOf(ev)!=='ended')b='<button class=\"sm\" data-act=\"join\" data-id=\"'+ev.id+'\" data-slot=\"'+s.slot+'\">'+L('Sign up','Inscrever')+'</button>';\n  if(mc&&showMgr)b+=(s.taken&&!s.mine?' <button class=\"d sm\" data-act=\"free\" data-id=\"'+ev.id+'\" data-slot=\"'+s.slot+'\">'+L('Free','Liberar')+'</button>':'')+' <button class=\"d sm\" data-act=\"rm\" data-id=\"'+ev.id+'\" data-slot=\"'+s.slot+'\">&times;</button>';\n  return'<div class=\"r\"><div class=\"n\">'+lbl+'<br>'+who+recLine(s,kind)+'</div><div>'+b+'</div></div>'}\nfunction render(){\n  var h='';if(!data.length)h='<div class=\"c m\">'+L('No events yet.','Nenhum evento ainda.')+'</div>';\n  data.forEach(function(e){var st=stateOf(e),np=e.pilots.filter(function(x){return x.taken}).length,nc=e.ctl.filter(function(x){return x.taken}).length;\n    h+='<div class=\"c\"><div class=\"t\"><b>'+esc(e.title)+'</b><span class=\"pill '+st+'\" id=\"p'+e.id+'\">'+st+'</span></div>'+\n      '<div class=\"m\">'+esc(utc(e.start))+' &middot; '+esc(loc(e.start))+' ('+L('your time','seu hor\u00e1rio')+')</div>'+\n      '<div class=\"cd\" id=\"cd'+e.id+'\">'+cd(e)+'</div>'+\n      (e.apt||e.route?'<div class=\"m\">'+(e.apt?esc(e.apt):'')+(e.apt&&e.route?' &middot; ':'')+esc(e.route)+'</div>':'')+\n      (e.desc?'<div class=\"m\" style=\"color:var(--txt)\">'+esc(e.desc)+'</div>':'')+\n      (st!=='upcoming'?recap(e):'')+\n      (e.pilots.length?'<div class=\"h\">'+L('PILOTS','PILOTOS')+' '+np+'/'+e.pilots.length+'</div>'+e.pilots.map(function(s){return slotRow(e,s,'p')}).join(''):'')+\n      (e.ctl.length?'<div class=\"h\">'+L('CONTROLLERS','CONTROLADORES')+' '+nc+'/'+e.ctl.length+'</div>'+e.ctl.map(function(s){return slotRow(e,s,'c')}).join(''):'')+\n      (mc&&showMgr?'<div style=\"margin-top:8px\"><button class=\"d sm\" data-act=\"del\" data-id=\"'+e.id+'\">'+L('Delete event','Excluir evento')+'</button></div>':'')+'</div>'});\n  $('list').innerHTML=h}\nfunction tick(){data.forEach(function(e){var c=$('cd'+e.id);if(c)c.textContent=cd(e);var p=$('p'+e.id);if(p){var st=stateOf(e);p.textContent=st;p.className='pill '+st}})}\nfunction load(){return api('GET','/api/events').then(function(r){if(r.s!==200){say('HTTP '+r.s);return}data=r.j.events||[];nowOff=(r.j.now||Date.now())-Date.now();if(r.j.account){acct=r.j.account;ls('afc_acct',acct)}else if(tok){tok='';acct='';ls('afc_token',null);ls('afc_acct',null)}hdr();render()})}\nfunction hdr(){$('ttl').textContent=L('Events','Eventos');$('who').textContent=tok&&acct?L('Signed in as ','Conectado como ')+acct:L('Not signed in','N\u00e3o conectado');\n  $('acctB').textContent=tok?L('Sign out','Sair'):L('Sign in','Entrar');$('mgrB').textContent=mc?(showMgr?L('Close manager','Fechar gerente'):'Manager'):'Manager';$('mgr').style.display=mc&&showMgr?'':'none'}\nfunction loginUI(on){$('login').style.display=on?'':'none';$('lgT').textContent=L('Sign in with your Aerofly Connect account','Entre com sua conta Aerofly Connect');$('un').placeholder=L('Account name','Nome da conta');$('pw').placeholder=L('Password','Senha');$('lgIn').textContent=L('Sign in','Entrar');$('lgReg').textContent=L('Create account','Criar conta');$('lgX').textContent=L('Cancel','Cancelar')}\n$('acctB').onclick=function(){if(tok){api('POST','/api/account/logout',{});tok='';acct='';ls('afc_token',null);ls('afc_acct',null);hdr();load()}else loginUI(true)};\n$('lgX').onclick=function(){loginUI(false)};\nfunction auth(path){var n=$('un').value.trim(),p=$('pw').value;if(!n||!p)return;fetch(path,{method:'POST',headers:{'X-API-Key':dev,'Content-Type':'application/json'},body:JSON.stringify({name:n,password:p})}).then(function(r){return r.json().then(function(j){return{s:r.status,j:j}})}).then(function(x){if(x.s<300&&x.j.token){tok=x.j.token;acct=x.j.name||n;ls('afc_token',tok);ls('afc_acct',acct);$('pw').value='';loginUI(false);say('');hdr();load()}else say(L('Could not sign in: ','N\u00e3o foi poss\u00edvel entrar: ')+(x.j.error||x.s))})}\n$('lgIn').onclick=function(){auth('/api/account/login')};$('lgReg').onclick=function(){auth('/api/account/register')};\n$('mgrB').onclick=function(){if(mc){showMgr=!showMgr;hdr();render();return}var c=prompt(L('Manager code','C\u00f3digo de gerente'));if(!c)return;mc=c.trim();api('GET','/api/health').then(function(r){if(r.j&&r.j.mgr){ls('afc_mgr',mc);showMgr=true;hdr();render()}else{mc='';say(L('Wrong manager code','C\u00f3digo de gerente errado'))}})};\n$('list').onclick=function(ev){var b=ev.target.closest('button[data-act]');if(!b)return;var a=b.getAttribute('data-act'),id=b.getAttribute('data-id'),slot=b.getAttribute('data-slot');say('');\n  var done=function(r){if(r.s>=300)err(r);else say('');load()};\n  if(a==='join'||a==='leave')api('POST','/api/events/'+(a==='join'?'signup':'leave'),{id:id,slot:slot}).then(done);\n  else if(a==='free'||a==='rm'){if(a==='rm'&&!confirm(L('Remove this slot?','Remover esta vaga?')))return;api('POST','/api/manager/events/free',{id:id,slot:slot,remove:a==='rm'}).then(done)}\n  else if(a==='del'){if(!confirm(L('Delete this event?','Excluir este evento?')))return;api('DELETE','/api/manager/events?id='+encodeURIComponent(id)).then(done)}};\n$('mgo').onclick=function(){var t=$('ms').value;if(!$('mt').value.trim()||!t){say('Title and start time needed');return}\n  var pil=$('mp').value.split('\\n').map(function(l){return l.trim().split(/\\s+/)}).filter(function(a){return a[0]}).map(function(a){return{callsign:a[0],dep:a[1]||'',arr:a[2]||''}});\n  var ctl=$('mc').value.split('\\n').map(function(l){return l.trim().split(/\\s+/)}).filter(function(a){return a[0]&&a[1]}).map(function(a){return{apt:a[0],pos:a[1]}});\n  api('PUT','/api/manager/events',{title:$('mt').value,desc:$('md').value,start:t+':00Z',duration_h:$('mh').value,apt:$('ma').value,route:$('mr').value,pilots:pil,ctl:ctl}).then(function(r){if(r.s>=300){err(r);return}say(L('Event created','Evento criado'));['mt','md','ms','ma','mr','mp','mc'].forEach(function(i){$(i).value=''});load()})};\nloginUI(false);hdr();load();setInterval(tick,1000);setInterval(load,60000);\n})();\n</script></body></html>\n";
